/* CSS PART 1 OF 2 */

/* DESIGN TOKENS */
:root {
  --ink: #202a2c;
  --ink-soft: #465355;
  --forest: #263e39;
  --forest-deep: #192e2a;
  --copper: #bd7950;
  --copper-dark: #965a38;
  --cream: #f5f2eb;
  --paper: #fffefa;
  --stone: #e7e3d9;
  --muted: #747c79;
  --white: #ffffff;

  --font-display: Georgia, "Times New Roman", serif;
  --font-body: "Helvetica Neue", Helvetica, Arial, sans-serif;

  --container: 1160px;
  --gutter: clamp(22px, 5vw, 76px);
  --section-space: clamp(76px, 9vw, 124px);

  --radius: 3px;
  --shadow: 0 18px 55px rgba(25, 46, 42, .13);
  --transition: 220ms ease;
}

/* RESET */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 90px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid var(--copper);
  outline-offset: 4px;
}

::selection {
  background: var(--copper);
  color: var(--white);
}

/* SHARED TYPOGRAPHY */
h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--ink);
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -.035em;
}

h1 {
  font-size: clamp(46px, 6.4vw, 82px);
}

h2 {
  font-size: clamp(36px, 4.5vw, 56px);
}

h3 {
  font-size: clamp(24px, 2.6vw, 32px);
}

p {
  margin: 0 0 20px;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--copper-dark);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 29px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 700px;
  margin-bottom: 24px;
}

.section-intro {
  max-width: 650px;
  color: var(--ink-soft);
  font-size: 17px;
  line-height: 1.85;
}

.text-accent {
  color: var(--copper);
}

.text-light {
  color: var(--white);
}

/* PAGE LAYOUT */
.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--cream {
  background: var(--cream);
}

.section--dark {
  background: var(--forest-deep);
  color: rgba(255, 255, 255, .8);
}

.section--dark h2,
.section--dark h3 {
  color: var(--white);
}

.section--dark .eyebrow {
  color: #dba27c;
}

/* HEADER AND NAVIGATION */
.site-header {
  position: relative;
  z-index: 20;
  background: var(--paper);
  border-bottom: 1px solid rgba(32, 42, 44, .09);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
}

.brand {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
}

.brand-logo {
  width: 58px;
  height: 58px;
  flex: 0 0 auto;
  object-fit: contain;
}

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  line-height: 1.2;
}

.brand-name {
  color: var(--forest-deep);
  font-family: var(--font-display);
  font-size: 19px;
  font-weight: 700;
  letter-spacing: -.035em;
}

.brand-descriptor {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.primary-nav {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(20px, 3vw, 38px);
}

.primary-nav > a:not(.button) {
  position: relative;
  padding-block: 12px;
  color: var(--ink-soft);
  font-size: 12px;
  font-weight: 700;
  transition: color var(--transition);
}

.primary-nav > a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 5px;
  left: 0;
  height: 1px;
  background: var(--copper);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.primary-nav > a:not(.button):hover {
  color: var(--copper-dark);
}

.primary-nav > a:not(.button):hover::after {
  transform: scaleX(1);
}

.header-phone {
  color: var(--forest);
  font-size: 13px;
  font-weight: 800;
  white-space: nowrap;
}

/* REUSABLE BUTTONS */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 15px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: .045em;
  line-height: 1.3;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
}

.button--primary {
  background: var(--copper);
  color: var(--white);
}

.button--primary:hover {
  background: var(--copper-dark);
}

.button--dark {
  background: var(--forest);
  color: var(--white);
}

.button--dark:hover {
  background: var(--forest-deep);
}

.button--outline {
  border-color: rgba(255, 255, 255, .65);
  background: transparent;
  color: var(--white);
}

.button--outline:hover {
  border-color: var(--white);
  background: var(--white);
  color: var(--forest-deep);
}

.button--light-outline {
  border-color: rgba(38, 62, 57, .35);
  background: transparent;
  color: var(--forest);
}

.button--light-outline:hover {
  border-color: var(--forest);
  background: var(--forest);
  color: var(--white);
}

.button-arrow {
  font-size: 18px;
  line-height: 1;
}

/* FULL-BLEED HERO */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, calc(100svh - 88px));
  align-items: center;
  overflow: hidden;
  isolation: isolate;
  background: var(--forest-deep);
  color: var(--white);
}

.hero-media {
  position: absolute;
  z-index: -2;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 53%;
}

.hero::before {
  position: absolute;
  z-index: -1;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(16, 34, 30, .91) 0%,
      rgba(16, 34, 30, .78) 38%,
      rgba(16, 34, 30, .34) 73%,
      rgba(16, 34, 30, .12) 100%
    ),
    linear-gradient(
      0deg,
      rgba(16, 34, 30, .43),
      transparent 45%
    );
  content: "";
}

.hero-content {
  width: min(760px, 75%);
  padding-block: 100px 116px;
}

.hero .eyebrow {
  color: #e5b08a;
}

.hero h1 {
  max-width: 760px;
  margin-bottom: 27px;
  color: var(--white);
}

.hero-description {
  max-width: 560px;
  margin-bottom: 35px;
  color: rgba(255, 255, 255, .88);
  font-size: clamp(16px, 1.5vw, 19px);
  line-height: 1.8;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero-proof {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 24px;
  margin-top: 52px;
  padding-top: 23px;
  border-top: 1px solid rgba(255, 255, 255, .28);
}

.hero-proof-item {
  display: flex;
  align-items: center;
  gap: 10px;
  color: rgba(255, 255, 255, .9);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .055em;
  text-transform: uppercase;
}

.hero-proof-number {
  color: #e5b08a;
  font-family: var(--font-display);
  font-size: 27px;
  line-height: 1;
}

/* INTRODUCTION / WHY CHOOSE US */
.intro-section {
  padding-block: var(--section-space);
}

.intro-layout {
  display: grid;
  grid-template-columns: .9fr 1.1fr;
  align-items: center;
  gap: clamp(48px, 8vw, 110px);
}

.intro-copy h2 {
  margin-bottom: 25px;
}

.intro-copy p {
  color: var(--ink-soft);
  line-height: 1.9;
}

.intro-image-wrap {
  position: relative;
  min-height: 430px;
}

.intro-image {
  width: 100%;
  height: 470px;
  object-fit: cover;
  object-position: center;
}

.intro-image-caption {
  position: absolute;
  right: -20px;
  bottom: 24px;
  max-width: 245px;
  padding: 20px 24px;
  background: var(--forest);
  color: var(--white);
  box-shadow: var(--shadow);
}

.intro-image-caption strong {
  display: block;
  margin-bottom: 4px;
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 400;
}

.intro-image-caption span {
  color: rgba(255, 255, 255, .78);
  font-size: 11px;
  line-height: 1.6;
}

/* PROJECT EXPERIENCE / ROOFING */
.projects-section {
  background: var(--cream);
}

.projects-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 48px;
}

.projects-heading .section-heading {
  margin-bottom: 0;
}

.projects-heading .section-intro {
  max-width: 380px;
}

.project-feature {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 490px;
  background: var(--paper);
}

.project-feature-image {
  width: 100%;
  height: 100%;
  min-height: 490px;
  object-fit: cover;
  object-position: center;
}

.project-feature-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  padding: clamp(34px, 6vw, 76px);
}

.project-feature-copy h3 {
  margin-bottom: 20px;
}

.project-feature-copy p {
  color: var(--ink-soft);
  line-height: 1.85;
}

.project-label {
  display: inline-block;
  margin-bottom: 17px;
  color: var(--copper-dark);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.project-gallery {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  margin-top: 24px;
}

.project-gallery-item {
  position: relative;
  min-height: 340px;
  overflow: hidden;
  background: var(--stone);
}

.project-gallery-item img {
  width: 100%;
  height: 100%;
  min-height: 340px;
  object-fit: cover;
  transition: transform 450ms ease;
}

.project-gallery-item:hover img {
  transform: scale(1.035);
}

.project-gallery-caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 30px 25px 20px;
  background: linear-gradient(transparent, rgba(20, 31, 28, .83));
  color: var(--white);
  font-family: var(--font-display);
  font-size: 21px;
}

/* GENERAL CONTRACTOR APPROACH */
.approach-layout {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: clamp(45px, 8vw, 105px);
  align-items: start;
}

.approach-heading {
  position: sticky;
  top: 35px;
}

.approach-heading h2 {
  margin-bottom: 22px;
}

.approach-heading p {
  color: var(--ink-soft);
  line-height: 1.85;
}

.approach-points {
  border-top: 1px solid var(--stone);
}

.approach-point {
  display: grid;
  grid-template-columns: 56px 1fr;
  gap: 22px;
  padding-block: 28px;
  border-bottom: 1px solid var(--stone);
}

.approach-number {
  color: var(--copper-dark);
  font-family: var(--font-display);
  font-size: 28px;
  line-height: 1.2;
}

.approach-point h3 {
  margin-bottom: 10px;
  font-size: 25px;
}

.approach-point p {
  margin-bottom: 0;
  color: var(--ink-soft);
  font-size: 15px;
  line-height: 1.8;
}

/* REDUCED MOTION */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}
